{
  "root": "main_stack",
  "state": {
    "greetings": [
      {
        "language": "Spanish",
        "greeting": "¡Hola, ¿cómo estás?"
      },
      {
        "language": "French",
        "greeting": "Bonjour, comment allez-vous ?"
      },
      {
        "language": "German",
        "greeting": "Hallo, wie geht es Ihnen?"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "subtitle",
        "greetings_table"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Common Greetings Translation",
        "variant": "h1"
      },
      "children": []
    },
    "subtitle": {
      "type": "Text",
      "props": {
        "text": "\"Hello, how are you?\" in Other Languages",
        "variant": "h2"
      },
      "children": []
    },
    "greetings_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "language",
            "label": "Language"
          },
          {
            "key": "greeting",
            "label": "Greeting"
          }
        ],
        "statePath": "/greetings",
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "language",
        "highlightColumns": [
          "greeting"
        ]
      },
      "children": []
    }
  }
}
